package br.gov.ma.pacodolumiar.semed.tecnico;
import android.Manifest;import android.app.*;import android.app.job.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.location.*;import android.net.Uri;import android.os.*;import android.webkit.*;import android.widget.*;import org.json.JSONObject;
public class MainActivity extends Activity {
 private WebView web;private final Handler handler=new Handler(Looper.getMainLooper());private LocationListener locationListener;private boolean requesting=false;private volatile boolean bridgeTrusted=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(22,25,29));web=new WebView(this);setContentView(web);web.setBackgroundColor(Color.rgb(243,244,245));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
  web.addJavascriptInterface(new Bridge(),"SemedNative");web.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri uri=r.getUrl();if(allowed(uri)&&uri.getPath().startsWith("/tecnico")&&!uri.getPath().endsWith(".apk"))return false;if(r.isForMainFrame()&&("https".equals(uri.getScheme())||"geo".equals(uri.getScheme()))){try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){Toast.makeText(MainActivity.this,"Nenhum aplicativo de mapas disponível.",Toast.LENGTH_LONG).show();}}return true;}
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return allowed(r.getUrl())?null:new WebResourceResponse("text/plain","UTF-8",403,"Blocked",null,new java.io.ByteArrayInputStream(new byte[0]));}
   @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){bridgeTrusted=false;}
   @Override public void onPageFinished(WebView v,String url){bridgeTrusted=trusted();CookieManager.getInstance().flush();}
  });web.loadUrl(Api.ORIGIN+"/tecnico");
 }
 private boolean allowed(Uri uri){return "https".equals(uri.getScheme())&&Api.ORIGIN.equals(uri.getScheme()+"://"+uri.getAuthority());}
 private boolean trusted(){return web!=null&&web.getUrl()!=null&&web.getUrl().startsWith(Api.ORIGIN+"/tecnico");}
 class Bridge {
  @JavascriptInterface public boolean hasQueueTracking(){JSONObject saved=TrackingStore.read(MainActivity.this);return bridgeTrusted&&saved!=null&&saved.optBoolean("authorized")&&!saved.optBoolean("stopping");}
  @JavascriptInterface public void requestLocation(){runOnUiThread(()->{if(!trusted())return;requesting=true;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},10);}else locate();});}
  @JavascriptInterface public void startTracking(String id,String csrf){runOnUiThread(()->{if(!trusted()||!id.matches("[a-fA-F0-9-]{36}")||csrf.length()>256)return;try{startForegroundService(new Intent(MainActivity.this,LegacyLocationService.class).putExtra("attendance",id).putExtra("csrf",csrf));}catch(Exception e){Toast.makeText(MainActivity.this,"Não foi possível iniciar o acompanhamento. Confira a localização.",Toast.LENGTH_LONG).show();}});}
  @JavascriptInterface public void stopTracking(){runOnUiThread(()->{if(trusted())stopService(new Intent(MainActivity.this,LegacyLocationService.class));});}
  @JavascriptInterface public String prepareQueueTracking(String user){if(!bridgeTrusted||!user.matches("[a-fA-F0-9-]{36}"))return "{}";try{return TrackingStore.prepare(MainActivity.this,user);}catch(Exception e){return "{\"error\":\"Não foi possível preparar o acompanhamento. Confira a conexão e reabra o app.\"}";}}
  @JavascriptInterface public void resumeQueueTracking(String user){runOnUiThread(()->{if(!trusted())return;JSONObject saved=TrackingStore.read(MainActivity.this);if(saved==null)return;if(!user.equals(saved.optString("user"))){LocationService.signOut(MainActivity.this);return;}stopService(new Intent(MainActivity.this,LegacyLocationService.class));LocationService.resume(MainActivity.this);});}
  @JavascriptInterface public void clearEndedTracking(String id){runOnUiThread(()->{if(!trusted())return;JSONObject saved=TrackingStore.read(MainActivity.this);if(saved!=null&&id.equals(saved.optString("id"))){stopService(new Intent(MainActivity.this,LocationService.class));TrackingStore.clear(MainActivity.this,id);}});}
  @JavascriptInterface public void stopQueueTracking(){runOnUiThread(()->{if(trusted())LocationService.signOut(MainActivity.this);});}
  @JavascriptInterface public void signedIn(String username){runOnUiThread(()->{if(!trusted())return;CookieManager.getInstance().flush();android.content.SharedPreferences p=getSharedPreferences("notices",MODE_PRIVATE);if(!username.equals(p.getString("user","")))p.edit().clear().putString("user",username).apply();((JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE)).schedule(new JobInfo.Builder(105,new ComponentName(MainActivity.this,NoticeJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000).build());if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);});}
  @JavascriptInterface public void signedOut(){runOnUiThread(()->{((JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE)).cancel(105);getSharedPreferences("notices",MODE_PRIVATE).edit().clear().apply();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancelAll();});}
 }
 @Override public void onRequestPermissionsResult(int req,String[] permissions,int[] grants){super.onRequestPermissionsResult(req,permissions,grants);if(req==10&&requesting){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)locate();else reply(null,"Permita a localização nas configurações do Android para iniciar.");}}
 private void locate(){clearLocation();requesting=true;LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);locationListener=new LocationListener(){public void onLocationChanged(Location l){if(System.currentTimeMillis()-l.getTime()>60000||l.getAccuracy()>5000||l.getAccuracy()<=0)return;reply(l,null);}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};
  boolean registered=false;for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(lm.isProviderEnabled(p)){lm.requestLocationUpdates(p,1000,0,locationListener,Looper.getMainLooper());registered=true;}}catch(SecurityException ignored){}
  if(!registered){reply(null,"Ative a localização do aparelho e tente novamente.");return;}handler.postDelayed(()->{if(requesting)reply(null,"Não foi possível obter uma posição atual. Confira o GPS e tente novamente.");},20000);
 }
 private void reply(Location l,String error){if(!requesting)return;requesting=false;clearLocation();try{JSONObject p=new JSONObject();if(error!=null)p.put("error",error);else{p.put("latitude",l.getLatitude());p.put("longitude",l.getLongitude());p.put("accuracy",l.getAccuracy());p.put("observedAt",l.getTime());}if(trusted())web.evaluateJavascript("window.semedReceiveLocation("+p.toString()+")",null);}catch(Exception ignored){}}
 private void clearLocation(){if(locationListener!=null){((LocationManager)getSystemService(LOCATION_SERVICE)).removeUpdates(locationListener);locationListener=null;}}
 @Override protected void onResume(){super.onResume();LocationService.resume(this);}
 @Override protected void onDestroy(){clearLocation();handler.removeCallbacksAndMessages(null);if(web!=null){web.removeJavascriptInterface("SemedNative");web.destroy();}super.onDestroy();}
 private void leavePage(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override public void onBackPressed(){if(!trusted()){leavePage();return;}web.evaluateJavascript("Boolean(window.semedHandleBack && window.semedHandleBack())",result->{if(!"true".equals(result)&&!isFinishing()&&!isDestroyed())leavePage();});}
}
